t=sqlite3.connect(S+'/t.db'); t.row_factory=sqlite3.Row
rows=t.execute('select * from identity_need_icf').fetchall()
need={r['need_code']:r for r in live.execute('select * from access_needs')}
idn={r['identity_code']:r for r in live.execute('select * from base_taxonomy_identity')}
icf={r['icf_code']:r for r in live.execute('select * from base_icf')}
nmap={(r['need_code'],r['icf_code']):r for r in live.execute('select * from access_need_icf')}
links={r['link_id']:r for r in live.execute('select * from identity_icf_map')}
tax=open('governance/functional-taxonomy.md').read()
ax={};st={}
for ln in tax.splitlines():
    m=re.match(r"\|\s*`(AX-[A-Z-]+)`\s*\|[^|]*\|([^|]*)\|([^|]*)\|\s*([A-Z]+)\s*\|",ln)
    if m: ax[m.group(1)]=set(re.findall(r"\b[bde]\d{3,4}\b",m.group(2))); st[m.group(1)]=m.group(4)
bad=collections.Counter(); ok=collections.Counter()
def chk(k,cond,msg):
    if cond: ok[k]+=1
    else: bad[k]+=1; print('FAIL',k,msg)
for r in rows:
    I,N,C,w=r['identity_code'],r['need_code'],r['icf_code'],r['warrant']
    key=f'{I}|{N}|{C}'
    m=re.search(r'Need (\S+) registry text: "([^"]*)"\. Identity (\S+): "([^"]*)"\. Code (\S+?)(?: \(title recorded in base_icf: "([^"]*)"\))?: (.*)$',w)
    chk('parse',bool(m),key)
    if not m: continue
    n2,qn,i2,qi,c2,title,rest=m.groups()
    chk('keys',(n2,i2,c2)==(N,I,C),key)
    chk('need quote in absorbs',qn in (need[N]['absorbs'] or ''),f'{key} {qn!r}')
    inname=qi in (idn[I]['display_name'] or ''); indesc=qi in (idn[I]['description'] or '')
    chk('identity quote in display_name/description',inname or indesc,f'{key} {qi!r}')
    if title is not None: chk('title',icf[C]['title']==title,key)
    else: chk('no title => null or e',icf[C]['title'] is None or C[0]=='e',f"{key} title={icf[C]['title']!r}")
    mm=re.search(r'access_need_icf holds (\S+) -> (\S+?)(?: \(annotated: (.*?)\))?[;.]',rest)
    if 'access_need_icf holds' in rest:
        chk('needmap parse',bool(mm),key)
        if mm:
            chk('needmap row',(mm.group(1),mm.group(2)) in nmap and (mm.group(1),mm.group(2))==(N,C),key)
    if 'annotated:' in rest:
        a=re.search(r'\(annotated: (.*)\)(?:;|\.$)',rest).group(1)
        chk('annotation',nmap[(N,C)]['notes']==a,f'{key} {a!r}')
        ok['rows copying notes']+=1
    else:
        if (N,C) in nmap and nmap[(N,C)]['notes']: print('note not shown',key)
    lm=re.search(r'identity_icf_map link ([\d/]+) holds it for (\S+?)[;.]',rest)
    if lm:
        ids=[int(x) for x in lm.group(1).split('/')]
        for i in ids:
            chk('link',i in links and links[i]['identity_code']==I and links[i]['icf_code']==C and links[i]['retired_at'] is None,f'{key} link {i}')
        allids=[l for l,v in links.items() if v['identity_code']==I and v['icf_code']==C and v['retired_at'] is None]
        chk('link complete',sorted(allids)==sorted(ids),key)
    else:
        chk('no link cited => none exists',not [l for l,v in links.items() if v['identity_code']==I and v['icf_code']==C],key)
    am=re.search(r'(AX-[A-Z-]+) \(status ([A-Z]+)\) lists it',rest)
    if am:
        chk('anchor',C in ax[am.group(1)],key); chk('status',st[am.group(1)]==am.group(2),key)
    if (N,C) not in nmap: chk('has tie','tie: ' in rest,key)
print('OK',dict(ok)); print('BAD',dict(bad))
# b-codes
print('b rows',[r['icf_code'] for r in rows if r['icf_code'].startswith('b')])
tj=json.load(open('scratchpad/session_2026-11-21-identity-need-icf-triples/triples.json'))
wj=json.load(open('scratchpad/session_2026-11-21-identity-need-icf-triples/withheld.json'))
print(len(tj),len(wj))
sqlset={(r['identity_code'],r['need_code'],r['icf_code']):r['warrant'] for r in rows}
print('triples==sql', {(x['identity'],x['need'],x['icf']):x['warrant'] for x in tj}==sqlset)
print('withheld in sql',[x for x in wj if (x['identity'],x['need'],x['icf']) in sqlset])
print('withheld',[(x['identity'],x['need'],x['icf'],x['support']) for x in wj])
print(collections.Counter(x['support'] for x in tj))
print('imap components',collections.Counter(v['icf_code'][0] for v in links.values()))
print('null titles',sum(1 for v in icf.values() if v['title'] is None),len(icf))
print('rows on null title',[f"{r['identity_code']}|{r['need_code']}|{r['icf_code']}" for r in rows if icf[r['icf_code']]['title'] is None])
